from pathlib import Path
import base64
import gzip
import subprocess

PAYLOAD = ""
patch_path = Path("tools/v019-decoded.patch")
patch_path.write_bytes(gzip.decompress(base64.b64decode(PAYLOAD)))
try:
    subprocess.run(["git", "apply", "--check", str(patch_path)], check=True)
    subprocess.run(["git", "apply", str(patch_path)], check=True)
finally:
    patch_path.unlink(missing_ok=True)
